import{_ as t,C as s,o as d,c as e,a3 as o,j as a,E as n,a as l}from"./chunks/framework.C6R8kWFE.js";const O=JSON.parse(`{"title":"1-dars (Mentor). Android nima va uning rivojlanish tarixi","description":"","frontmatter":{"title":"1-dars (Mentor). Android nima va uning rivojlanish tarixi","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_dars","dars":{"sinf":{"name":"9-sinf (Android)","link":"/mentor/9-sinf-android/"},"week":{"n":1,"link":"/mentor/9-sinf-android/hafta-01/"},"g":1,"title":"Android nima va uning rivojlanish tarixi","lead":"Android nima va uning rivojlanish tarixi: mobil OS tarixi, Google, versiyalar va O'zbekiston ekotizimi","slide":"/slaydlar/9-sinf-android/hafta-01/dars-1.html","test":"/slaydlar/9-sinf-android/hafta-01/dars-1-test.html","student_link":"/9-sinf-android/hafta-01/dars-1","tabs":[{"g":1,"link":"/mentor/9-sinf-android/hafta-01/dars-1","current":true},{"g":2,"link":"/mentor/9-sinf-android/hafta-01/dars-2","current":false},{"g":3,"link":"/mentor/9-sinf-android/hafta-01/dars-3","current":false}],"prev":null,"next":{"g":2,"title":"Android tizimi va uning arxitekturasi","link":"/mentor/9-sinf-android/hafta-01/dars-2"}}},"headers":[],"relativePath":"mentor/9-sinf-android/hafta-01/dars-1.md","filePath":"mentor/9-sinf-android/hafta-01/dars-1.md"}`),h={name:"mentor/9-sinf-android/hafta-01/dars-1.md"},m={class:"blk"},g={id:"_1-dars-maqsadi-va-kutiladigan-natijalar",tabindex:"-1"},u={class:"blk"},v={id:"_2-dars-rejasi-80-daqiqa",tabindex:"-1"},b={class:"blk"},y={id:"_3-nazariy-tushunchalar-mentor-uchun-to-liq-konspekt",tabindex:"-1"},q={class:"blk"},k={id:"_4-darsda-bajariladigan-amaliy-topshiriqlar-va-yechimlari",tabindex:"-1"},c={class:"blk"},p={id:"_5-tezkor-savol-javob-blits-savollar",tabindex:"-1"},f={class:"blk"},A={id:"_6-mentor-uchun-amaliy-tavsiyalar",tabindex:"-1"};function _(x,i,z,T,S,P){const r=s("Icon");return d(),e("div",null,[i[18]||(i[18]=o("<p><strong>Sinf:</strong> 9-sinf (Android dasturlash)<br><strong>Hafta:</strong> 1-hafta<br><strong>Dars tartibi:</strong> 1-dars (umumiy 102 darsdan 1-darsi)<br><strong>Davomiyligi:</strong> 80 daqiqa<br><strong>Format:</strong> Ma&#39;ruza va interaktiv kirish mashg&#39;uloti</p><hr>",2)),a("div",m,[a("h2",g,[n(r,{name:"file-text"}),i[0]||(i[0]=l(" 1. Dars maqsadi va kutiladigan natijalar ",-1)),i[1]||(i[1]=a("a",{class:"header-anchor",href:"#_1-dars-maqsadi-va-kutiladigan-natijalar","aria-label":'Permalink to "<Icon name="file-text" /> 1. Dars maqsadi va kutiladigan natijalar"'},"​",-1))]),i[2]||(i[2]=o("<ul><li><strong>Maqsad:</strong> O&#39;quvchilarga mobil operatsion tizimlarning evolyutsiyasi, Android tizimining vujudga kelishi, Google tomonidan rivojlantirilishi, versiyalar ketma-ketligi hamda Androidning zamonaviy dunyoda va O&#39;zbekiston raqamli iqtisodiyotidagi o&#39;rnini tushuntirish.</li><li><strong>Kutiladigan natijalar:</strong><ul><li>O&#39;quvchi Android operatsion tizimining mohiyati va ochiq kodli (open source / AOSP) ekanligini anglaydi;</li><li>Android Inc. asoschilari (Andy Rubin, Rich Miner, Nick Sears, Chris White) va 2005-yilda Google sotib olganini biladi;</li><li>Ilk tijoriy Android qurilmasi (HTC Dream / T-Mobile G1, 2008-yil) xususiyatlarini tushuntira oladi;</li><li>Android versiyalarining nomlanish tizimini (shirinliklar davri: Cupcake&#39;dan Pie&#39;gacha va zamonaviy raqamlar davri: Android 10 dan 15 gacha) taqqoslay oladi;</li><li>O&#39;zbekistondagi ommabop Android ilovalari (Click, Payme, Apelsin, Yandex Go, MyTaxi, EduOn) misolida mobil dasturlashning ijtimoiy-iqtisodiy ahamiyatini tahlil qila oladi.</li></ul></li></ul><hr>",2))]),a("div",u,[a("h2",v,[n(r,{name:"file-text"}),i[3]||(i[3]=l(" 2. Dars rejasi (80 daqiqa) ",-1)),i[4]||(i[4]=a("a",{class:"header-anchor",href:"#_2-dars-rejasi-80-daqiqa","aria-label":'Permalink to "<Icon name="file-text" /> 2. Dars rejasi (80 daqiqa)"'},"​",-1))]),i[5]||(i[5]=o('<table tabindex="0"><thead><tr><th>Vaqt</th><th>Bosqich</th><th>Tavsif</th></tr></thead><tbody><tr><td><strong>00–10 daq</strong></td><td>Tashkiliy qism va kirish</td><td>Salomlashish, yo&#39;nalish mazmuni bilan tanishtirish, qiziqtiruvchi savol: &quot;Dunyoda har kuni nechta Android qurilmasi faollashadi?&quot;</td></tr><tr><td><strong>10–30 daq</strong></td><td>Yangi mavzu: Tarix va evolyutsiya</td><td>Mobil operatsion tizimlar tarixi (Symbian, BlackBerry, iOS), Android Inc. va Andy Rubin, Google xaridi, HTC Dream</td></tr><tr><td><strong>30–50 daq</strong></td><td>Yangi mavzu: Versiyalar va ochiq kod falsafasi</td><td>Cupcake&#39;dan Android 15 gacha bo&#39;lgan rivojlanish, AOSP (Android Open Source Project) va turli qobiqlar (OneUI, MIUI, HyperOS)</td></tr><tr><td><strong>50–65 daq</strong></td><td>Amaliy keys va guruhlarda muhokama</td><td>O&#39;zbekistondagi mobil ilovalar ekotizimi, smartfonlardagi Android versiyalari va texnik imkoniyatlar tahlili</td></tr><tr><td><strong>65–75 daq</strong></td><td>Mustahkamlash va test sinovi</td><td>Tezkor savol-javob (blits), atamalarni takrorlash</td></tr><tr><td><strong>75–80 daq</strong></td><td>Xulosa va uyga vazifa</td><td>Darsni sarhisob qilish, o&#39;quvchilarni baholash va uyga vazifa berish</td></tr></tbody></table><hr>',2))]),a("div",b,[a("h2",y,[n(r,{name:"file-text"}),i[6]||(i[6]=l(" 3. Nazariy tushunchalar (Mentor uchun to'liq konspekt) ",-1)),i[7]||(i[7]=a("a",{class:"header-anchor",href:"#_3-nazariy-tushunchalar-mentor-uchun-to-liq-konspekt","aria-label":`Permalink to "<Icon name="file-text" /> 3. Nazariy tushunchalar (Mentor uchun to'liq konspekt)"`},"​",-1))]),i[8]||(i[8]=o('<h3 id="_3-1-androidning-mohiyati-va-boshqaruv-mexanizmi" tabindex="-1">3.1. Androidning mohiyati va boshqaruv mexanizmi <a class="header-anchor" href="#_3-1-androidning-mohiyati-va-boshqaruv-mexanizmi" aria-label="Permalink to &quot;3.1. Androidning mohiyati va boshqaruv mexanizmi&quot;">​</a></h3><p>Android — bu sensorli ekranli mobil qurilmalar (smartfonlar, planshetlar) va aqlli gadjetlar uchun maxsus moslashtirilgan, <strong>Linux yadrosiga (Linux Kernel)</strong> asoslangan ochiq kodli operatsion tizimdir. Uni <strong>Google</strong> boshchiligidagi Open Handset Alliance konsortsiumi rivojlantiradi.</p><p>Operatsion tizim sifatida Android quyidagi asosiy jarayonlarni boshqaradi:</p><ol><li><strong>Apparat ta&#39;minoti va resurslar boshqaruvi:</strong> Protsessor (CPU), operativ xotira (RAM), doimiy xotira (Flash Storage) resurslarini taqsimlaydi;</li><li><strong>Periferiya va sensorlar nazorati:</strong> Kamera, mikrafon, akselerometr, giroskop, GPS, barmoq izi skaneri va boshqa modullar faoliyatini muvofiqlashtiradi;</li><li><strong>Ilovalarning xavfsiz izolyatsiyasi:</strong> Har bir ilova alohida Linux foydalanuvchisi (UID) va alohida jarayonda xavfsiz «sandbox» rejimida ishlaydi.</li></ol><h3 id="_3-2-yaratilish-tarixi-va-google-sotib-olishi" tabindex="-1">3.2. Yaratilish tarixi va Google sotib olishi <a class="header-anchor" href="#_3-2-yaratilish-tarixi-va-google-sotib-olishi" aria-label="Permalink to &quot;3.2. Yaratilish tarixi va Google sotib olishi&quot;">​</a></h3><ul><li><strong>2003-yil (Android Inc.):</strong> AQSHning Kaliforniya shtati Palo-Alto shahrida Andy Rubin, Rich Miner, Nick Sears va Chris White Android Inc. kompaniyasiga asos solishdi. Dastlabki maqsad — raqamli kameralar uchun aqlli operatsion tizim yaratish edi. Ammo kameralar bozori torayib, mobil telefonlar jadal rivojlanayotganini ko&#39;rgan jamoa diqqatini smartfonlarga qaratdi.</li><li><strong>2005-yil (Google sotib olishi):</strong> Google kompaniyasi Android Inc.ni taxminan 50 million dollarga sotib oldi. Andy Rubin Google vitse-prezidenti sifatida tizimni rivojlantirishga rahbarlik qildi. Google bepul, ochiq va moslashuvchan platforma yaratish orqali barcha qidiruv va internet xizmatlarini mobil muhitga integratsiya qilishni maqsad qildi.</li><li><strong>2007-yil:</strong> Open Handset Alliance (Google, HTC, Sony, Dell, Intel, Qualcomm, Samsung) tashkil etildi va Android rasman ommaga e&#39;lon qilindi.</li><li><strong>2008-yil 23-sentabr:</strong> Tarixdagi birinchi tijoriy Android smartfoni — <strong>HTC Dream (AQSHda T-Mobile G1)</strong> sotuvga chiqdi. Qurilma sensorli ekran, to&#39;liq QWERTY klaviatura, Wi-Fi, GPS va Android Market (hozirgi Google Play) do&#39;koniga ega edi.</li></ul><h3 id="_3-3-versiyalar-tarixi-shirinliklar-nomlaridan-raqamlarga" tabindex="-1">3.3. Versiyalar tarixi: Shirinliklar nomlaridan raqamlarga <a class="header-anchor" href="#_3-3-versiyalar-tarixi-shirinliklar-nomlaridan-raqamlarga" aria-label="Permalink to &quot;3.3. Versiyalar tarixi: Shirinliklar nomlaridan raqamlarga&quot;">​</a></h3><p>2019-yilgacha Google har bir yangi Android versiyasini alifbo tartibida shirinliklar yoki pishiriqlar nomi bilan atagan:</p><ul><li><strong>1.5 Cupcake (2009):</strong> Ekran klaviaturasi va vidjetlar qo&#39;shildi;</li><li><strong>1.6 Donut (2009):</strong> Har xil ekran o&#39;lchamlari qo&#39;llab-quvvatlandi;</li><li><strong>2.0/2.1 Eclair (2009):</strong> Google Maps navigatsiyasi, ko&#39;p hisobli pochta;</li><li><strong>2.2 Froyo (2010):</strong> JIT kompilyatori (tezlik 2-5 barobar oshdi), Wi-Fi hotspot;</li><li><strong>2.3 Gingerbread (2010):</strong> NFC qo&#39;llab-quvvatlovi, o&#39;yinlar uchun optimallashuv;</li><li><strong>4.0 Ice Cream Sandwich (2011):</strong> Holo dizayn tili, Face Unlock;</li><li><strong>4.1–4.3 Jelly Bean (2012):</strong> Project Butter (silliq 60 fps interfeys), Google Now;</li><li><strong>4.4 KitKat (2013):</strong> 512 MB operativ xotiraga ega arzon telefonlarda ham silliq ishlash;</li><li><strong>5.0 Lollipop (2014):</strong> <strong>Material Design</strong> dizayn tili, ART (Android Runtime) asosiy runtime sifatida kiritildi;</li><li><strong>6.0 Marshmallow (2015):</strong> Runtime permissions (dastur ishlayotgan paytda ruxsat so&#39;rash);</li><li><strong>7.0 Nougat (2016):</strong> Split-screen (ekranni ikkiga bo&#39;lish), tezkor javob;</li><li><strong>8.0 Oreo (2017):</strong> Project Treble (OS yangilanishlarini tezlashtirish);</li><li><strong>9.0 Pie (2018):</strong> Moslashuvchan batareya (Adaptive Battery), imo-ishoralar bilan boshqarish.</li></ul><p><strong>Raqamli nomlash davri (2019-yildan):</strong> Global foydalanuvchilar madaniy farqlari tufayli shirinlik nomlarini tushunishda qiyinchilikka duch kelmasligi uchun Google rasmiy nomlarni raqamga o&#39;tkazdi (garchi ichki kod nomlari shirinlik bo&#39;lib qolgan bo&#39;lsa-da):</p><ul><li><strong>Android 10 (2019):</strong> Dark Theme (to&#39;liq qora rejim), 5G qo&#39;llab-quvvatlovi;</li><li><strong>Android 11 (2020):</strong> Bildirishnomalardagi muloqotlar (Conversations), bir martalik ruxsatlar;</li><li><strong>Android 12 (2021):</strong> <strong>Material You (Material 3)</strong> — fon rasmiga qarab ranglarni avtomatik moslashtiruvchi dinamik interfeys;</li><li><strong>Android 13 (2022):</strong> Ilova darajasida til tanlash, bildirishnoma ruxsatnomasi (POST_NOTIFICATIONS);</li><li><strong>Android 14 (2023):</strong> Ultra HDR tasvirlar, batareya unumdorligi, kattalashtirilgan shriftlar;</li><li><strong>Android 15 (2024–2025):</strong> Private Space (maxfiy bo&#39;lim), sun&#39;iy intellekt (Gemini Nano) integratsiyasi, ilovalarni sun&#39;iy ushlab turishni cheklash.</li></ul><h3 id="_3-4-ochiq-manba-aosp-va-ishlab-chiqaruvchilar-qobiqlari" tabindex="-1">3.4. Ochiq manba (AOSP) va ishlab chiqaruvchilar qobiqlari <a class="header-anchor" href="#_3-4-ochiq-manba-aosp-va-ishlab-chiqaruvchilar-qobiqlari" aria-label="Permalink to &quot;3.4. Ochiq manba (AOSP) va ishlab chiqaruvchilar qobiqlari&quot;">​</a></h3><p>Android asosida <strong>AOSP (Android Open Source Project)</strong> yotadi. Bu kod ochiq Apache 2.0 litsenziyasi ostida tarqatiladi. Shuning uchun smartfon ishlab chiqaruvchilari AOSP negizida o&#39;zlarining shaxsiy interfeyslarini (firmware) yaratadilar:</p><ul><li>Samsung — <strong>One UI</strong></li><li>Xiaomi — <strong>MIUI / HyperOS</strong></li><li>OnePlus — <strong>OxygenOS</strong></li><li>Google Pixel — <strong>Pixel UI (toza Android)</strong></li></ul><hr>',15))]),a("div",q,[a("h2",k,[n(r,{name:"file-text"}),i[9]||(i[9]=l(" 4. Darsda bajariladigan amaliy topshiriqlar va yechimlari ",-1)),i[10]||(i[10]=a("a",{class:"header-anchor",href:"#_4-darsda-bajariladigan-amaliy-topshiriqlar-va-yechimlari","aria-label":'Permalink to "<Icon name="file-text" /> 4. Darsda bajariladigan amaliy topshiriqlar va yechimlari"'},"​",-1))]),i[11]||(i[11]=o('<h3 id="_1-topshiriq-smartfon-android-versiyasi-va-texnik-parametrlarini-aniqlash-oson" tabindex="-1">1-topshiriq. Smartfon Android versiyasi va texnik parametrlarini aniqlash (Oson) <a class="header-anchor" href="#_1-topshiriq-smartfon-android-versiyasi-va-texnik-parametrlarini-aniqlash-oson" aria-label="Permalink to &quot;1-topshiriq. Smartfon Android versiyasi va texnik parametrlarini aniqlash (Oson)&quot;">​</a></h3><p><strong>Topshiriq:</strong> Har bir o&#39;quvchi o&#39;z smartfonining (yoki sinfdagi planshetning) «Sozlamalar» (Settings) bo&#39;limiga kirib:</p><ol><li>Android versiyasini aniqlaydi;</li><li>«Android versiyasi» ustiga 3-4 marta tez bosib, yashirin «Easter Egg» animatsiyasini ochadi;</li><li>Qurilma modeli, protsessor turi va operativ xotirasini daftarga yozadi.</li></ol><p><strong>Yechim:</strong> O&#39;quvchi: Sozlamalar -&gt; Telefon haqida (About phone) -&gt; Dasturiy ta&#39;minot ma&#39;lumotlari (Software information) bo&#39;limiga kiradi. Android versiyasi ustiga bir necha bor bosganda, masalan Android 14 bo&#39;lsa kosmik kema animatsiyasi chiqadi. Barcha parametrlar qayd etiladi.</p><h3 id="_2-topshiriq-android-versiyalari-taqqoslash-jadvali-o-rta" tabindex="-1">2-topshiriq. Android versiyalari taqqoslash jadvali (O&#39;rta) <a class="header-anchor" href="#_2-topshiriq-android-versiyalari-taqqoslash-jadvali-o-rta" aria-label="Permalink to &quot;2-topshiriq. Android versiyalari taqqoslash jadvali (O&#39;rta)&quot;">​</a></h3><p><strong>Topshiriq:</strong> Android 4.4 (KitKat), Android 5.0 (Lollipop) va Android 12 (Material You) versiyalarini asosiy texnik o&#39;zgarishlari bo&#39;yicha 3 ustunli jadvalga joylashtiring.</p><p><strong>Yechim:</strong></p><table tabindex="0"><thead><tr><th>Xususiyat</th><th>Android 4.4 KitKat</th><th>Android 5.0 Lollipop</th><th>Android 12</th></tr></thead><tbody><tr><td>Chiqqan yili</td><td>2013</td><td>2014</td><td>2021</td></tr><tr><td>Dizayn tili</td><td>Holo (qora/ko&#39;k)</td><td>Material Design (tekis kartalar)</td><td>Material You (dinamik ranglar)</td></tr><tr><td>Runtime</td><td>Dalvik (standart)</td><td>ART (birlamchi qilib kiritildi)</td><td>ART (yanada tezlashgan)</td></tr><tr><td>Asosiy yangilik</td><td>512MB RAM bilan ishlash</td><td>64-bit CPU, yangi bildirishnomalar</td><td>Dynamic Theming, Privacy Dashboard</td></tr></tbody></table><h3 id="_3-topshiriq-o-zbekiston-mobil-ilovalar-ekotizimi-tahlili-qiyin" tabindex="-1">3-topshiriq. O&#39;zbekiston mobil ilovalar ekotizimi tahlili (Qiyin) <a class="header-anchor" href="#_3-topshiriq-o-zbekiston-mobil-ilovalar-ekotizimi-tahlili-qiyin" aria-label="Permalink to &quot;3-topshiriq. O&#39;zbekiston mobil ilovalar ekotizimi tahlili (Qiyin)&quot;">​</a></h3><p><strong>Topshiriq:</strong> Quyidagi mahalliy mobil ilovalardan kamida 4 tasini tanlab, ular qanday hayotiy muammoni hal qilishi va qaysi funksiyalari tufayli ommalashganini tahlil qiling: <code>Click</code>, <code>Payme</code>, <code>Yandex Go</code>, <code>MyTaxi</code>, <code>EduOn</code>, <code>Kundalik / eMaktab</code>.</p><p><strong>Yechim:</strong></p><ol><li><strong>Click / Payme:</strong> Bank kartalarini bog&#39;lash, P2P pul o&#39;tkazmalari, kommunal to&#39;lovlar, QR-kod orqali do&#39;konda to&#39;lash muammosini hal qiladi. Foydalanuvchilar navbatda turmasdan telefon orqali to&#39;lov qiladi.</li><li><strong>Yandex Go / MyTaxi:</strong> Yo&#39;lovchi va haydovchini GPS orqali avtomatik bog&#39;laydi. Narx oldindan aniq, mashinaning kelish yo&#39;nalishi xaritada ko&#39;rinadi.</li><li><strong>EduOn / eMaktab:</strong> Ta&#39;lim resurslariga masofaviy kirish, dars jadvallari va baholarni ota-onalar va o&#39;quvchilarga onlayn ko&#39;rsatish imkonini beradi.</li></ol><hr>',13))]),a("div",c,[a("h2",p,[n(r,{name:"file-text"}),i[12]||(i[12]=l(" 5. Tezkor savol-javob (Blits-savollar) ",-1)),i[13]||(i[13]=a("a",{class:"header-anchor",href:"#_5-tezkor-savol-javob-blits-savollar","aria-label":'Permalink to "<Icon name="file-text" /> 5. Tezkor savol-javob (Blits-savollar)"'},"​",-1))]),i[14]||(i[14]=o("<ol><li><strong>Android Inc. kompaniyasiga kim asos solgan?</strong><br><em>Javob:</em> Andy Rubin, Rich Miner, Nick Sears va Chris White (2003-yil).</li><li><strong>Google Android kompaniyasini nechanchi yilda sotib olgan?</strong><br><em>Javob:</em> 2005-yilda.</li><li><strong>Tarixdagi birinchi Android smartfoni qaysi va u qachon chiqqan?</strong><br><em>Javob:</em> HTC Dream (T-Mobile G1), 2008-yil sentabr.</li><li><strong>Android operatsion tizimining asosi qaysi yadroga qurilgan?</strong><br><em>Javob:</em> Linux yadrosiga (Linux Kernel).</li><li><strong>Nima uchun Android versiyalari endi shirinliklar bilan nomlanmaydi?</strong><br><em>Javob:</em> Global miqyosda foydalanuvchilar chalkashmasligi va versiyalarni raqamlar bo&#39;yicha tushunish qulay bo&#39;lishi uchun (Android 10 dan boshlab).</li><li><strong>AOSP nima degani?</strong><br><em>Javob:</em> Android Open Source Project — Androidning ochiq kodli loyihasi.</li></ol><hr>",2))]),a("div",f,[a("h2",A,[n(r,{name:"file-text"}),i[15]||(i[15]=l(" 6. Mentor uchun amaliy tavsiyalar ",-1)),i[16]||(i[16]=a("a",{class:"header-anchor",href:"#_6-mentor-uchun-amaliy-tavsiyalar","aria-label":'Permalink to "<Icon name="file-text" /> 6. Mentor uchun amaliy tavsiyalar"'},"​",-1))]),i[17]||(i[17]=a("ul",null,[a("li",null,"O'quvchilarda dasturlashga nisbatan ishtiyoq uyg'otish uchun telefonlaridagi ilovalarning yaratilish tarixi bilan darsni bog'lang."),a("li",null,"O'quvchilarga Android faqat telefonlarda emas, balki televizor, avtomobil va soatlarda ham ishlashini ta'kidlang (bu 3-dars mavzusiga ko'prik bo'ladi)."),a("li",null,"HTC Dream va zamonaviy flagmanlarni taqqoslab, texnologiya 15-18 yil ichida qanchalik ulkan masofani bosib o'tganini ko'rsating.")],-1))])])}const I=t(h,[["render",_]]);export{O as __pageData,I as default};
